"""Authored causal decision rules for every CounselBench-100 matter.

These rows are deliberately matter-specific.  The generator supplies raw facts
for a twelve-item portfolio, but this file defines the legal/business question,
the observation that matters, the controlling authority, and the scoped action.
No generated evidence file contains the resulting disposition.
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class DecisionRule:
    question: str
    observation: str
    authority: str
    recommended: str
    unsafe_shortcut: str
    register_action: str

    @property
    def signature(self) -> tuple[str, ...]:
        return (
            self.question,
            self.observation,
            self.authority,
            self.recommended,
            self.unsafe_shortcut,
            self.register_action,
        )


