def _parse_rows() -> dict[str, DecisionRule]:
    rules: dict[str, DecisionRule] = {}
    for line_number, line in enumerate(_ROWS.splitlines(), 1):
        fields = [field.strip() for field in line.split("|")]
        if len(fields) != 7:
            raise ValueError(
                f"decision rule line {line_number} has {len(fields)} fields, expected 7"
            )
        slug, question, observation, authority, recommended, unsafe, register = fields
        if slug in rules:
            raise ValueError(f"duplicate decision rule for {slug}")
        rules[slug] = DecisionRule(
            question=question,
            observation=observation,
            authority=authority,
            recommended=recommended,
            unsafe_shortcut=unsafe,
            register_action=register,
        )
    if len(rules) != 100:
        raise ValueError(f"expected 100 decision rules, found {len(rules)}")
    if len({rule.signature for rule in rules.values()}) != 100:
        raise ValueError("decision rule signatures must be unique")
    return rules


DECISION_RULES = _parse_rows()


def validate_decision_rules(slugs: set[str]) -> None:
    missing = slugs - set(DECISION_RULES)
    extra = set(DECISION_RULES) - slugs
    if missing or extra:
        raise ValueError(
            f"decision rule mismatch: missing={sorted(missing)}, extra={sorted(extra)}"
        )
